template:
struct DSU {
    vector<int> parent, size;
    int count;                                            // number of live sets
    DSU(int n) : parent(n), size(n, 1), count(n) { iota(parent.begin(), parent.end(), 0); }

    int find(int x) {                                     // with path compression
        while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }  // halving
        return x;
    }
    // Recursive version, easier to read:  return parent[x] == x ? x : parent[x] = find(parent[x]);

    bool unite(int a, int b) {                            // returns false if already joined
        a = find(a); b = find(b);
        if (a == b) return false;                         // redundant edge / cycle
        if (size[a] < size[b]) swap(a, b);                // union by size: small under big
        parent[b] = a; size[a] += size[b]; --count;
        return true;
    }
    bool same(int a, int b) { return find(a) == find(b); }
};

// Number of connected components from an edge list.
int countComponents(int n, vector<vector<int>>& edges) {
    DSU d(n);
    for (auto& e : edges) d.unite(e[0], e[1]);
    return d.count;
}

// Redundant Connection: the first edge whose unite() returns false closes a cycle.
vector<int> findRedundantConnection(vector<vector<int>>& edges) {
    DSU d(edges.size() + 1);                              // nodes are 1..n
    for (auto& e : edges) if (!d.unite(e[0], e[1])) return e;
    return {};
}

